INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9133, 'plPL', 'Lot do Srebrnej Luny', '$N, za naprawdę skromną opłatą mogę posłać cię w szybki lot przez przestworza na grzbiecie jednego z tych wspaniałych stworzeń. A zapewniam cię, że to bezpieczniejsze niż wędrówka pieszo!$B$BGdy dotrzesz do Srebrnej Luny, odszukaj Sathrena Lazurowego Świtu na Targowisku.$B$BPorozmawiaj ze mną ponownie, gdy uznasz, że jesteś $ggotów:gotowa; stawić czoła przestworzom.', 'Wykup lot do Srebrnej Luny i dostarcz list przewozowy kwatermistrzyni Lymel Sathrenowi Lazurowemu Świtowi w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9134, 'plPL', 'Mistrzyni lotów Zmierzch', 'Nie wygląda na to, żebyś $gmiał:miała; ze sobą wóz albo juczne zwierzę, więc lepiej odeślę z tobą tylko tyle, ile zdołasz unieść. Jeśli $grozmawiałeś:rozmawiałaś; już z mistrzem lotów Słonecznym Skrzydłem w Trankwillienie, $gpowinieneś:powinnaś; jak najszybciej dostarczyć to kwatermistrzyni Lymel, lecąc z powrotem.$B$BZanieś te towary do ostatecznej kontroli mistrzyni lotów Zmierzch, tuż za Bramą Pasterza Srebrnej Luny.', 'Dostarcz towary kwatermistrzyni Lymel do mistrzyni lotów Zmierzch, tuż za Bramą Pasterza Srebrnej Luny.', '', '', '', '', '', '', 0),
(9135, 'plPL', 'Powrót do kwatermistrzyni Lymel', 'Z tego, co widzę, wszystko się zgadza. Moim zdaniem Porzuceni nadstawili za nas karku i jesteśmy im coś winni, nawet jeśli wszyscy są szpetni i gniją.$B$BPytanie więc brzmi: czy $grozmawiałeś:rozmawiałaś; już z mistrzem lotów Słonecznym Skrzydłem w Trankwillienie? Jeśli tak, wystarczy, że uiścisz niewielką opłatę i szybko polecisz z powrotem.$B$BDaj znać, gdy będziesz $ggotów:gotowa;.', 'Wykup lot powrotny do Trankwillienu w Widmowych Ziemiach i dostarcz towary kwatermistrzyni Lymel samej kwatermistrzyni w Trankwillienie.', '', '', '', '', '', '', 0),
(9328, 'plPL', 'Bohater sin\'dorei', 'To początek nowego rozdziału w historii naszej rasy, $N. Odzyskamy nasze ziemie i umocnimy więź z Sylwaną i jej sojusznikami.$B$BZanieś głowę zdrajcy lordowi regentowi Lor\'themarowi Theronowi w Srebrnej Lunie. Z pewnością zechce jak najprędzej usłyszeć te wieści.', 'Zanieś głowę Dar\'Khana Lor\'themarowi Theronowi w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9489, 'plPL', 'Oczyszczanie Trupiej Blizny', '$N, dobrze, że jesteś. Plaga atakuje nasze miasto z tak nieprzejednaną nienawiścią, że obawiam się, iż morale naszej straży się załamuje.$b$bPospiesz na Trupią Bliznę, tuż na południe od miasta, gdzie w gotowości czeka Jaela ze swoimi tropicielami. Napełnij ich mocą Światła swoimi błogosławieństwami.', 'Rzuć Słowo mocy: Wytrwałość na 6 tropicieli Wszechpieśni na Trupiej Bliźnie.', '', 'Wróć do Ponarisa na Placu Sokolego Skrzydła w Gaju Wszechpieśni.', 'Pobłogosławiony tropiciel Wszechpieśni', '', '', '', 0),
(9529, 'plPL', 'Kamień', 'Nie wątpię, że twój chochlik okazał się użytecznym, a czasem i zabawnym sługą, lecz nadszedł czas, byś $gpodporządkował:podporządkowała; sobie potężniejszego demona: wędrowca Pustki.$b$bIdź w dół Trupiej Blizny, aż do miejsca, gdzie przecina ją Rzeka Elrendar. Tuż na południe od rzeki odszukaj jeden z kamieni lśniących błękitnym blaskiem i weź go. Tam ukaże ci się twoja ścieżka.', 'Zdobądź kamień pustki na Trupiej Bliźnie.', '', '', '', '', '', '', 0),
(9532, 'plPL', 'Odnajdź Keltusa Mrocznego Liścia', '$n, jeden z naszych zwiadowców zbyt gorliwie oddał się swoim obowiązkom. Niestrudzenie śledzi naszych wrogów, lecz nie przysyła żadnych raportów ze swoich ustaleń.$b$bMusisz odnaleźć tego szpiega, Keltusa Mrocznego Liścia, przekonać go, by oddał raport, i jak najszybciej mi go dostarczyć. Znajdziesz go daleko na południowym zachodzie, tam gdzie Rzeka Elrendar rozwidla się i opływa Wioskę Złotej Mgły. Jego zwierzyną są nocne elfy z An\'daroth, więc nie będzie daleko od nich.', 'Odnajdź Keltusa Mrocznego Liścia.', '', '', '', '', '', '', 0),
(9618, 'plPL', 'Dostarcz raporty', 'Twoja zręczność rąk zrobiła na mnie wrażenie. Nie ma wątpliwości, że mogę ci powierzyć dostarczenie tych raportów Zelanisowi.', 'Zanieś raporty Keltusa Mrocznego Liścia Zelanisowi w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9619, 'plPL', 'Runa przywołania', 'Kamień pustki ukazuje wizję kilkupiętrowego budynku nawiedzanego przez upiorne postacie. Obraz na przemian wyostrza się i rozmywa, a w polu widzenia pojawiają się kolejne budynki, więc nabierasz przekonania, że to Wioska Złotej Mgły.$b$bNagle przemykają przed tobą dachy i korony drzew, ukazując drogę do Wioski Złotej Mgły wzdłuż Rzeki Elrendar na zachód.$b$bNa miejscu użyj kamienia pustki przy runie przywołania na szczycie środkowego budynku i pokonaj przyzwanego wędrowca Pustki. Dopiero wtedy możesz wrócić do swojej nauczycielki.', 'Użyj kamienia pustki, by przyzwać wędrowca Pustki w Wiosce Złotej Mgły, pokonaj go i wróć do Talionii w Srebrnej Lunie.', '', 'Wróć do Talionii w Sanktuarium w Srebrnej Lunie.', '', '', '', '', 0),
(9677, 'plPL', 'Wezwanie od rycerza-lorda Krwawego Męstwa', '$N, $gosiągnąłeś:osiągnęłaś; znakomite wyniki w początkowym szkoleniu i $gwyróżniłeś:wyróżniłaś; się spośród tych, którzy pragną zostać Krwawymi Rycerzami. Jesteś $ggotów:gotowa; przystąpić do kolejnego etapu szkolenia, dlatego sam rycerz-lord Krwawe Męstwo pragnie z tobą porozmawiać.$B$BNie wątpię, że rycerz-lord Krwawe Męstwo zamierza wyznaczyć ci próbę, która sprawdzi twoje umiejętności i wyszkolenie. Znajdziesz go w siedzibie Krwawych Rycerzy na Skwerze Obieżyświatów w Srebrnej Lunie. Powodzenia, $N.', 'Porozmawiaj z rycerzem-lordem Krwawym Męstwem na Skwerze Obieżyświatów w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9678, 'plPL', 'Pierwsza próba', 'Wiele $gnauczyłeś:nauczyłaś; się o walce i przelewie krwi, $gnowicjuszu:nowicjuszko;, lecz nasz zakon to coś znacznie więcej.$B$BPanowanie nad Światłem wymaga skupionego umysłu i ogromnej siły woli. Bez nich jesteś niewiele $glepszy:lepsza; od ulicznego zbira.$B$BW północno-wschodniej części Widmowych Ziem leży wyspa zwana Wyspą Udręk, na której szlifujemy te umiejętności. W płytkiej jaskini znajdziesz tam palenisko. Uklęknij przed nim, rozpal je i skup się na tym, co ujrzysz przed oczami.', 'Udaj się na wyspę opisaną przez rycerza-lorda Krwawe Męstwo, odnajdź jaskinię i rozpal palenisko. Gdy Pierwsza próba dobiegnie końca, wróć do rycerza-lorda Krwawego Męstwa w Srebrnej Lunie.', '', 'Wróć do rycerza-lorda Krwawego Męstwa w Gaju Wszechpieśni.', 'Przejdź Pierwszą próbę', '', '', '', 0),
(9681, 'plPL', 'Studium mocy', 'Nie uważaj mnie za przesadnie surowego, $N. Sangrias dobrze wiedział, po co go wysyłam. Rozumiał i przyjął swój obowiązek – jest wzorem dla wszystkich aspirujących Krwawych Rycerzy.$B$BMoje słowa nie są mową pogrzebową, $N. Służba Sangriasa jeszcze się nie skończyła, a ty staniesz się narzędziem jego wskrzeszenia.$B$BTwoja nauka dróg zakonu dopiero się zaczęła. Po zdradzie Kael\'thasa i utracie naszego źródła mocy musisz poznać nowe sposoby władania Światłem. Odszukaj magistra Astalora Krwioprzysięgłego.', 'Porozmawiaj z magistrem Astalorem Krwioprzysięgłym w ukrytej komnacie pod siedzibą Krwawych Rycerzy.', '', '', '', '', '', '', 0),
(9684, 'plPL', 'Zawładnięcie Światłem', 'Weź to naczynie, $N. Nałożone na nie zaklęcie pozwoli ci wyssać ostatnie resztki Światła otaczającego tych magistrów. Niegdyś doglądali uwięzionego naaru i wciąż pozostała w nich część jego energii.$B$BWystarczy jej akurat, by przywrócić życie twojemu towarzyszowi.$B$BNie martw się o magistrów, $N. Zadbałem o nich, a lord Solanar zapewnia mnie, że Lady Liadrin już teraz szuka nowego źródła mocy.', 'Użyj lśniącego naczynia na krwawych elfach magistrach, by je napełnić, i wróć do rycerza-lorda Krwawego Męstwa w Srebrnej Lunie.', '', 'Wróć do rycerza-lorda Krwawego Męstwa w Gaju Wszechpieśni.', '', '', '', '', 0),
(9685, 'plPL', 'Odkupienie poległego', 'Podczas gdy $gprzygotowywałeś:przygotowywałaś; naczynie, wysłałem grupę nowicjuszy po Sangriasa Ciche Ostrze. Znajdziesz go wraz z opiekunem na najwyższym piętrze karczmy w Srebrnej Lunie. Udaj się tam co sił i uwolnij magię naczynia, by przywrócić go do życia.$B$BCzas nagli, $N. Jeśli będzie martwy zbyt długo, nawet Światło nie zdoła nam go zwrócić. Wróć do mnie, gdy wskrzesisz Sangriasa.', 'Zanieś napełnione lśniące naczynie do karczmy w Srebrnej Lunie i użyj jego magii, by wskrzesić Sangriasa Cichego Ostrza.', '', 'Wróć do rycerza-lorda Krwawego Męstwa w Gaju Wszechpieśni.', 'Wskrześ Sangriasa Cichego Ostrza', '', '', '', 0),
(9686, 'plPL', 'Druga próba', 'Stoisz u progu rangi adepta w zakonie, $N. Najpierw jednak musisz dowieść, że jesteś tego $ggodzien:godna;, podejmując kolejną próbę.$B$BDruga próba różni się od pierwszej tym, że tym razem nie będzie niespodzianek. Wyzwanie jest proste: musisz stanąć do walki z czterema czempionami Krwawych Rycerzy i ich pokonać.$B$BGdy przyjmiesz wyzwanie, pośrodku pawilonu pojawi się kryształ. Dotknij go, by rozpocząć próbę, i nie oddalaj się od budynku.$B$BJesteś $ggotów:gotowa;?', 'Przejdź Drugą próbę, pokonując czempiona Krwawego Gniewu, czempiona Rozdzieracza Światła, czempiona Chyże Ostrze i czempiona Słońcobija w pawilonie niedaleko mistrza Keleruna Krwawej Żałoby.', 'Przejdź Drugą próbę', 'Wróć do mistrza Keleruna Krwawej Żałoby w Ruinach Srebrnej Luny w Gaju Wszechpieśni.', '', '', '', '', 0),
(9690, 'plPL', 'Druga próba', '$N, $gnowicjuszu:nowicjuszko;, ciężko $gpracowałeś:pracowałaś;, by opanować moce Światła zdobyte przez naszych magistrów. $GPoznałeś:Poznałaś; źródło naszych zdolności i obowiązki Krwawego Rycerza.$B$BNadszedł czas, byś $gprzeszedł:przeszła; Drugą próbę i $gpowalczył:powalczyła; o rangę adepta wśród Krwawych Rycerzy. Próbę przeprowadzi mistrz Kelerun Krwawa Żałoba w miejscu na północ od miasta. Udaj się na północ przez Ruiny Srebrnej Luny i skręć na wschodnią ścieżkę tuż przed mostem na Wyspę Słońcobieżców.', 'Zgłoś się do mistrza Keleruna Krwawej Żałoby.', '', '', '', '', '', '', 0),
(9691, 'plPL', 'Powrót do Srebrnej Luny', 'Wróć do Srebrnej Luny i niezwłocznie zamelduj się u rycerza-lorda Krwawego Męstwa. Twoje przybycie powie mu wszystko, co musi wiedzieć o wyniku próby.$B$BOpowie ci o zadaniach, które pozostały ci na drodze do rangi adepta. Unieś dumnie głowę, $N. Wielu podejmuje tę próbę, lecz niewielu wraca, by opowiedzieć o swoim sukcesie.', 'Wróć do rycerza-lorda Krwawego Męstwa w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9692, 'plPL', 'Ścieżka adepta', 'Nim $gświeżo upieczony adept:świeżo upieczona adeptka; zostanie $gprzyjęty:przyjęta; w szeregi Krwawych Rycerzy, musi zdobyć surowce potrzebne do wykonania charakterystycznej broni naszego zakonu – korseki hartowanej krwią.$B$BMusisz też zasłużyć na prawo do noszenia insygnium naszego zakonu. Gdy zakon powstawał, wykuto i rozdano określoną liczbę insygniów, więc każdy nowy adept dziedziczy swoje po weteranie. Twoje insygnium pochodzi od poległego rycerza, który dzielnie poprowadził szturm na Ostoję Śmierci.$B$BPrzygotowałem notatki, które cię poprowadzą.', 'Przynieś skażony klejnot Kor, skrzynię krwawokutych sztab, porcję krwi gniewnych i insygnium Krwawych Rycerzy rycerzowi-lordowi Krwawemu Męstwu w Srebrnej Lunie.', '', 'Wróć do rycerza-lorda Krwawego Męstwa w Gaju Wszechpieśni.', '', '', '', '', 0),
(9707, 'plPL', 'Wykuwanie broni', 'Po raz kolejny $gdowiodłeś:dowiodłaś; przed zakonem i towarzyszami, że jesteś $ggodzien:godna; ich uznania. Z wielką przyjemnością nadaję ci rangę adepta, $N. Sam książę Kael\'thas byłby z ciebie dumny.$B$BKażdy z nas uznałby za zaszczyt walkę u twego boku na polu bitwy. Bądź nadal wzorem dla tych, którzy pragną do nas dołączyć. Nie okazuj ani litości, ani słabości, niestrudzenie broń swego ludu i swych braci i doskonal panowanie nad Światłem.$B$BA teraz odbierz broń godną twojej nowej rangi.', 'Zanieś skrzynię z materiałami Bemarrinowi w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9710, 'plPL', 'Korseka hartowana krwią', 'Wszystko przygotowane, $N. Już wkrótce będziesz $gmiał:miała; broń godną twojej nowej pozycji.', 'Zaczekaj, aż Bemarrin wykuje twoją broń.', '', '', '', '', '', '', 0),
(9721, 'plPL', 'Wezwanie od lorda Solanara', 'Twoje oddanie zakonowi i awans w jego szeregach nie przeszły bez echa. Co więcej, lord Solanar Krwawy Gniew, prawa ręka Lady Liadrin i sam wielki bohater, pragnie z tobą porozmawiać.$B$BTo rzadki zaszczyt, $N. Zwykle lord Solanar zostawia mi sprawy szeregowych członków zakonu, lecz tobą zainteresował się osobiście. Nie zwlekaj, $N.', 'Porozmawiaj z lordem Solanarem Krwawym Gniewem w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(9722, 'plPL', 'Ścieżka mistrza', 'W szeregach naszego zakonu istnieje wewnętrzny krąg elitarnych rycerzy. Jego członkowie to najbardziej oddani, najbieglejsi i najgodniejsi zaufania spośród wszystkich Krwawych Rycerzy, osobiście wybierani przez przywództwo zakonu. Większość rozpoznaje mistrzów po prostu po ich wierzchowcach – thalasyjskich szarżownikach.$B$BKażdy kandydat musi mieć w kręgu swojego poręczyciela i dowieść oddania naczelnym zasadom zakonu.$B$BPostanowiłem zostać twoim poręczycielem w staraniach o tytuł mistrza Krwawych Rycerzy, jeśli tego pragniesz.', 'Porozmawiaj ponownie z lordem Solanarem Krwawym Gniewem, by przyjąć jego propozycję poręczenia.', '', '', '', '', '', '', 0),
(9723, 'plPL', 'Gest oddania', 'Lojalność Krwawego Rycerza nie kończy się na czubku $gjego:jej; ostrza, $N. Zakon wymaga od swoich członków więcej niż samej musztry i walki. Prawdziwy rycerz uczestniczy we wszystkich działaniach zakonu, nawet w tych, które na pierwszy rzut oka nie wydają się chwalebne.$B$BTo pierwsze zadanie nie wymaga wiele walki i nie przyniesie chwały, lecz bez takiego wkładu zakon by się rozpadł. Dam ci listę rzeczy, których ludzie magistra Astalora Krwioprzysięgłego potrzebują, by zaopatrywać nas w energię Światła do naszej magii.', 'Przynieś 40 sztuk runicznej tkaniny, 6 sztabek arkanitu, 10 pęków słonecznej trawy, 5 mrocznych run i 150 sztuk złota lordowi Solanarowi Krwawemu Gniewowi w Srebrnej Lunie.', '', 'Wróć do lorda Solanara Krwawego Gniewu w Srebrnej Lunie.', '', '', '', '', 0),
(9725, 'plPL', 'Dowód lojalności', 'My, Krwawi Rycerze, jesteśmy zobowiązani bronić Quel\'Thalas, $N. To podstawa twojego szkolenia. Nasi wrogowie są zażarci i nieustępliwi. Srebrna Luna i jej lud pozostają wolni dzięki naszym wysiłkom i wsparciu sojuszników.$B$BOtrzymałem niepokojące raporty o ponownej obecności Plagi na południowy wschód od naszej granicy ze Wschodnimi Plagowiskami. Oddział inżynierów oblężniczych Plagi wraz ze sprzętem najwyraźniej szykuje się do ataku na Widmowe Ziemie. Nie możemy dopuścić, by im się powiodło.', 'Lord Solanar Krwawy Gniew w Srebrnej Lunie chce, byś $gzniszczył:zniszczyła; 3 wozy z mięsem Plagi i $gzabił:zabiła; 15 inżynierów oblężniczych Plagi.', '', 'Wróć do lorda Solanara Krwawego Gniewu w Srebrnej Lunie.', '', 'Zniszcz wozy z mięsem Plagi', '', '', 0),
(9735, 'plPL', 'Prawdziwi mistrzowie Światła', 'Mistrz Krwawych Rycerzy posiada niezwykłą umiejętność władania Światłem i splatania go w sposób, którego inni, tak zwani „paladyni”, nigdy nie pojmą. Nie przeszkadza im to jednak gardzić nami za to, że wyzwoliliśmy prawdziwy potencjał Światła.$B$BMusimy wysłać im wiadomość i pokazać, że nie należy z nami igrać. To, co zamierzam, nie będzie ani krótkie, ani łatwe, ale jeśli jesteś $gzdecydowany:zdecydowana;, pierwszym krokiem będzie przeniknięcie do skrzydła bibliotecznego Opactwa Dłoni Tyra i zdobycie fiolki wody święconej z Dłoni Tyra.', 'Lord Solanar Krwawy Gniew w Srebrnej Lunie chce, byś $gprzyniósł:przyniosła; mu fiolkę wody święconej z Dłoni Tyra.', '', 'Wróć do lorda Solanara Krwawego Gniewu w Srebrnej Lunie.', '', '', '', '', 0),
(9736, 'plPL', 'Prawdziwi mistrzowie Światła', 'Skoro mamy już wodę, będziemy potrzebować kilku odczynników w ściśle określonych ilościach. Niektóre z tych substancji są rzadkie i drogie, $N, ale znalazłem źródła dwóch z nich.$B$BTajemny katalizator kupisz u Zalle, sprzedawczyni składników w jednym ze sklepów przy placu w pobliżu Trupiej Blizny. Proszek zmierzchu ma w ofercie Darlia, handlarka truciznami urzędująca w pobliżu nauczycieli łotrów w Morderczym Zgiełku.$B$BBy dokończyć mieszankę, będę też potrzebował azerothiańskiego diamentu i nieskazitelnego czarnego diamentu.', 'Lord Solanar Krwawy Gniew w Srebrnej Lunie chce, byś $gprzyniósł:przyniosła; mu 1 tajemny katalizator, 1 proszek zmierzchu, 1 azerothiański diament i 1 nieskazitelny czarny diament.', '', 'Wróć do lorda Solanara Krwawego Gniewu w Srebrnej Lunie.', '', '', '', '', 0),
(9737, 'plPL', 'Prawdziwi mistrzowie Światła', 'To nasza droga korzystania ze Światła jest prawdziwa, $N. Aby pokazać tym, którzy nazywają się „paladynami”, jak bardzo błądzą, zamierzam wysłać im wiadomość, której nie sposób źle odczytać.$B$BKaplica Alonsusa, w której założono Zakon Srebrnej Dłoni, zdaje się nietknięta zniszczeniem, jakie spadło na Stratholm. Wieczny płomień kaplicy zapewnia jej ochronę Światła, lecz gdy ugasisz go tą mieszanką, ochrona zniknie. Kaplica spłonie, a nasze panowanie nad Światłem zostanie dowiedzione całemu światu.', 'Użyj mieszanki gaszącej przy wiecznym płomieniu w Kaplicy Alonsusa, by zdjąć z niej ochronę Światła. Bądź $ggotów:gotowa; do walki z każdym, kto spróbuje bronić kaplicy.', '', 'Wróć do lorda Solanara Krwawego Gniewu w Srebrnej Lunie.', 'Zdejmij ochronę z Kaplicy Alonsusa', '', '', '', 0),
(9811, 'plPL', 'Przyjaciel sin\'dorei', 'To początek nowego rozdziału w historii krwawych elfów, $N. $GPomogłeś:Pomogłaś; umocnić więź między moją rasą a twoją.$B$BZanieś głowę zdrajcy lordowi regentowi Lor\'themarowi Theronowi w Srebrnej Lunie. Z pewnością zechce jak najprędzej usłyszeć te wieści.', 'Zanieś głowę Dar\'Khana Lor\'themarowi Theronowi w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(10359, 'plPL', 'Dar wełnianego płótna', '', '', '', 'Wróć do Sorima Pieśni Światła w Gaju Wszechpieśni.', '', '', '', '', 0),
(10360, 'plPL', 'Dar jedwabnego płótna', '', '', '', 'Wróć do Sorima Pieśni Światła w Gaju Wszechpieśni.', '', '', '', '', 0),
(10361, 'plPL', 'Dar tkaniny magów', '', '', '', 'Wróć do Sorima Pieśni Światła w Gaju Wszechpieśni.', '', '', '', '', 0),
(10362, 'plPL', 'Dar runicznej tkaniny', '', '', '', 'Wróć do Sorima Pieśni Światła w Gaju Wszechpieśni.', '', '', '', '', 0),
(10363, 'plPL', 'Więcej runicznej tkaniny', '', '', '', 'Wróć do Sorima Pieśni Światła w Gaju Wszechpieśni.', '', '', '', '', 0),
(10372, 'plPL', 'Dyskretne zapytanie', 'Eralan, moja znajoma z Trankwillienu, rozpytuje o pomoc w pewnej pilnej robocie.$B$BNie wiem, co ma na myśli, bo nie zadaję pytań, ale ty $gdowiodłeś:dowiodłaś;, że jesteś aż nadto $gzdolny:zdolna;. Chcę, żebyś $gudał:udała; się do Trankwillienu w Widmowych Ziemiach i $gzamienił:zamieniła; słowo z Eralan.$B$BBywa nieco szorstka, ale można jej zaufać.', 'Porozmawiaj z Eralan w Trankwillienie.', '', '', '', '', '', '', 0),
(10933, 'plPL', 'Powrót do Srebrnej Luny', 'Twój mistrz Aldrae ze Srebrnej Luny prosi, żebyś się u niego $gstawił:stawiła;. Chodzi o twoje szkolenie, ale nic więcej nie wiem.', 'Porozmawiaj z Aldrae w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(10934, 'plPL', 'Powrót do Srebrnej Luny', 'Twój mistrz Aldrae ze Srebrnej Luny prosi, żebyś się u niego $gstawił:stawiła;. Chodzi o twoje szkolenie, ale nic więcej nie wiem.', 'Porozmawiaj z Aldrae w Srebrnej Lunie.', '', '', '', '', '', '', 0),
(12816, 'plPL', 'Zbadaj Plagę pod Srebrną Luną', 'Król Lisz nasłał nieumarłych pod same nasze drzwi; nie możemy stać bezczynnie! Z pewnością staniesz w obronie Srebrnej Luny przed tymi przeklętymi najeźdźcami? $b $bNa zewnątrz widać dziwne runiczne kręgi, jaśniejące tą samą energią, która otacza nieumarłych i nekropolię w górze. Na pewno mają jakieś znaczenie i chcę, żebyś $gdowiedział:dowiedziała; się jakie. Przy okazji przetrzeb szeregi tych potworności; przynieś mi dowód ich śmierci razem z tym, co ustalisz, a wynagrodzę cię. Ruszaj!', 'Zdobądź trzy przygasłe nekrotyczne kamienie od sług Plagi pod Srebrną Luną i zbadaj jaśniejące runiczne kręgi w pobliżu ich obozu.', 'Zbadaj krąg', 'Wróć do porucznik Julek w Gaju Wszechpieśni.', '', '', '', '', 0),
(24615, 'plPL', 'Prezent dla lorda regenta Quel\'Thalas', 'Chcesz zrobić uroczą bransoletkę z talizmanami dla lorda regenta Quel\'Thalas? Na pewno będzie zachwycony.$B$BMasz już zestaw kolekcjonera uroczych talizmanów?', 'Podaruj uroczą bransoletkę z talizmanami Lor\'themarowi Theronowi w Srebrnej Lunie.', '', 'Wróć do Lor\'themara Therona w Srebrnej Lunie.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9133, 'plPL', 'Co to ma być? Czyżby przegniły mózg Lymel w końcu wyciekł jej z głowy? Ona chce tego wszystkiego?!$B$B$GPrzyprowadziłeś:Przyprowadziłaś; kogoś, kto pomoże ci to zabrać z powrotem?', 0),
(9134, 'plPL', 'Z powrotem do Trankwillienu w Widmowych Ziemiach? Jasne, migiem cię tam dostarczę!', 0),
(9135, 'plPL', 'Cóż, skoro powiedział, że reszta szybko dotrze lądem, uwierzę mu na słowo. Przez ten krótki czas, odkąd razem pracujemy, jeszcze nigdy nie zawiódł z dostawą.$B$BDziękuję, $N, przynosisz chlubę sin\'dorei! Proszę, weź te monety... cały dzień tylko pobrzękiwały mi w kieszeni.', 0),
(9328, 'plPL', 'Oto twarz, której nie spodziewałem się ujrzeć tak prędko.$B$BTo doprawdy dobre wieści, $N, i to na więcej sposobów, niż możesz sobie wyobrazić.', 0),
(9489, 'plPL', 'Tropiciele już mówią o twoich błogosławieństwach z podziwem i szacunkiem. Teraz widzisz, jak Światło nam służy – pozwala pomagać innym, lecz dopiero wtedy, gdy pomożemy samym sobie.', 0),
(9529, 'plPL', 'Gdy wpatrujesz się w kamień, obraz przed twoimi oczami zaczyna wirować...', 0),
(9532, 'plPL', 'Mam nadzieję, że widzisz, jak głęboko się ukrywam... a przynajmniej ukrywałem.', 0),
(9618, 'plPL', 'Wszystkie te raporty są od Keltusa? No, nie próżnował, to pewne.$B$BKeltus to łotr nad łotrami – rzadko wykonuje rozkazy co do joty i często bierze sprawy w swoje ręce! Nie zrozum mnie jednak źle: to jeden z moich najbardziej zaufanych szpiegów i bez niego bylibyśmy zgubieni.$B$B$GWykonałeś:Wykonałaś; dziś wzorową robotę. Przyjmij to ostrze i wbij je w plecy naszego wroga.', 0),
(9619, 'plPL', 'Jestem pod wrażeniem, że stoisz tu przede mną, $N. Niejeden uczeń zginął w starciu z wędrowcem Pustki, a nawet przez sam kamień pustki.$B$BWędrowiec Pustki jest teraz na twoje rozkazy. Dobrze wykorzystaj swojego nowego sługę.', 0),
(9677, 'plPL', 'Witaj, $gmłody nowicjuszu:młoda nowicjuszko;. To, że tak szybko $godpowiedziałeś:odpowiedziałaś; na moje wezwanie, dobrze o tobie świadczy.$B$BDarujmy sobie zatem uprzejmości – najlepiej zostawić je dworzanom i im podobnym.$B$BTwoje szybkie postępy zwróciły moją uwagę, $N. Przekonamy się, czy $gwziąłeś:wzięłaś; sobie lekcje do serca.', 0),
(9678, 'plPL', 'Wiem, co musi ci teraz chodzić po głowie.$B$BTak, to ja wysłałem Sangriasa, by cię zabił.$B$BNie obrażaj się, $N – to była niezbędna próba. Krwawi Rycerze są bractwem, lecz musimy mieć pewność, że nasi bracia są zawsze czujni i gotowi. Czy trzeba było odebrać Sangriasowi życie, by ci to uzmysłowić?$B$BTak – i jest to równie ważna część twojego szkolenia jak każde ćwiczenie z mieczem.', 0),
(9681, 'plPL', 'Witaj, $gmłody paladynie:młoda paladynko;.$B$BMoc Krwawych Rycerzy pochodzi od istoty o niezmierzonej potędze.$B$B<Magister wskazuje gestem wielką, uwięzioną istotę pośrodku komnaty.>$B$BCzyż nie jest wspaniała? To dar od naszego ukochanego księcia Kael\'thasa i fundament panowania Krwawych Rycerzy nad Światłem. Istota ta niechętnie użycza nam swej mocy, opracowaliśmy więc metodę, by odbierać ją na naszych warunkach.', 0),
(9684, 'plPL', 'Dobra robota, $N. Moce, którymi obdarza Światło, nigdy nie przyjdą Krwawym Rycerzom „naturalnie”, ale nie jesteśmy tak naiwni, by dać się powstrzymać woli jednej istoty, choćby najpotężniejszej.$B$BTo nasze mistrzostwo w tajemnej sztuce otworzyło przed tobą tę ścieżkę i te moce, $gnowicjuszu:nowicjuszko;. Niewielu ma dość silne nerwy czy talent, by nimi władać, ale wiem, że nie zawiedziesz zakonu.', 0),
(9685, 'plPL', 'Witaj z powrotem, $gnowicjuszu:nowicjuszko;. Teraz, gdy znasz prawdę o źródle naszej mocy i $gdowiodłeś:dowiodłaś; swojej biegłości we władaniu nią, obdarzę cię zdolnością wskrzeszania poległych na polu bitwy.$B$BPozostań $gwierny:wierna; zakonowi i przykładaj się do szkolenia, a twoja moc będzie wciąż rosła.', 0),
(9686, 'plPL', 'Dobra robota, $N! $GDowiodłeś:Dowiodłaś;, że jesteś $ggodzien:godna; pełnego członkostwa w zakonie Krwawych Rycerzy i wyniesienia do rangi adepta. Zanim jednak zostaniesz $gprzyjęty:przyjęta;, musisz wykonać jeszcze kilka zadań.', 0),
(9690, 'plPL', 'Gdy będziesz $ggotów:gotowa;, opowiem ci więcej o próbie, która cię czeka. Przygotuj się i porozmawiaj ze mną ponownie, gdy zechcesz zacząć.', 0),
(9691, 'plPL', 'Wiedziałem, że stać cię na przejście próby, $N. Pozostałe obowiązki są głównie ceremonialne, lecz wcale nie mniej niebezpieczne niż stanięcie oko w oko z jednym z naszych czempionów, który dobył broni. Słuchaj uważnie, a powiem ci, co jeszcze musisz zrobić, by objąć nową rangę.', 0),
(9692, 'plPL', 'Znakomicie, $N. Wszystko jest na miejscu. Pozostało tylko wykuć broń.', 0),
(9707, 'plPL', 'Wygląda na to, że masz wszystko, czego mi trzeba. Zaczynajmy!', 0),
(9710, 'plPL', 'Proszę, $N. Dobrze jej używaj w służbie Srebrnej Luny i swojego zakonu.', 0),
(9721, 'plPL', 'Wkrótce omówimy cel twojej wizyty. Najpierw jednak pozwól mi powiedzieć, że twoja służba i biegłość we władaniu Światłem naprawdę zrobiły na mnie wrażenie.', 0),
(9722, 'plPL', 'To, że $gprzyjąłeś:przyjęłaś; moją propozycję, dobrze o tobie świadczy, $N. Życzę ci powodzenia w zadaniach, które zaraz ci wyznaczę, choć jestem pewien, że okażesz się aż nadto $gzdolny:zdolna;.$B$BPrzedstawię je po kolei, od najłatwiejszego do najtrudniejszego, a zaczniemy, gdy będziesz $ggotów:gotowa;.', 0),
(9723, 'plPL', 'Znakomicie. Wygląda na to, że wszystko się zgadza.$B$BNie martw się. W następnym zadaniu będziesz $gmiał:miała; mnóstwo okazji, by znów użyć broni, obiecuję.$B$BKażę któremuś z nowicjuszy zanieść to wszystko magistrowi Astalorowi. Nie ma potrzeby wysyłać cię z tak błahym poleceniem, gdy czekają ważniejsze sprawy.', 0),
(9725, 'plPL', '$GDowiodłeś:Dowiodłaś; swojej lojalności wobec ojczyzny i oddania potrzebom zakonu, $N. Mam dla ciebie jeszcze jedno, ostatnie zadanie, zanim będziesz $gmógł:mogła; ubiegać się o tytuł mistrza.', 0),
(9735, 'plPL', 'Hmm... to dość niewielka ilość, ale jeśli będziemy ostrożni, powinna wystarczyć. Widzisz, Szkarłatna Krucjata uważa się za oddaną Światłu. Przypuszczam, że na swój wypaczony sposób wciąż taka jest – i właśnie to zamierzam wykorzystać.$B$BIch zbłąkana gorliwość skaziła nawet błogosławieństwo wypowiedziane nad tą wodą, dzięki czemu idealnie nadaje się do moich celów.', 0),
(9736, 'plPL', 'Skoro mamy już wszystkie odczynniki, mogę przygotować mieszankę.$B$B<Na twarzy Lady Liadrin powoli pojawia się uśmiech.>$B$BWszystko układa się idealnie, $N. Gdy skończę, przekażę ci szczegóły tego, co jeszcze pozostało do zrobienia.', 0),
(9737, 'plPL', 'Dobra robota, $N. Wszyscy, którzy chcieliby nam się przeciwstawić, powinni wziąć sobie do serca ostrzeżenie, które $gprzekazałeś:przekazałaś;. Nasi wrogowie muszą wiedzieć, że grozi im niebezpieczeństwo – od najpośledniejszego piechura po $Gnajpotężniejszego bohatera:najpotężniejszą bohaterkę;.$B$B$GZasłużyłeś:Zasłużyłaś; na miejsce w szeregach mistrzów. Twoje oddanie i biegłość są przykładem dla wszystkich Krwawych Rycerzy. Na znak twojej nowej pozycji obdarzam cię umiejętnością przyzywania thalasyjskiego szarżownika i dowodzenia nim.', 0),
(9811, 'plPL', 'A więc to ty $gzabiłeś:zabiłaś; Dar\'Khana? Imponujące. Mam przeczucie, że mój lud i twój wkrótce bardzo się zaprzyjaźnią.', 0),
(10372, 'plPL', 'Zaczynałam się zastanawiać, czy Zelanis dostał ten list.$B$BDobrze. Bierzmy się do roboty.', 0),
(11772, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Gaju Wszechpieśni!', 0),
(11848, 'plPL', 'Uczcij płomień Gaju Wszechpieśni!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9133, 'plPL', 'Niezłą listę tu masz, $gprzyjacielu:przyjaciółko;. Pozwól, że rzucę na nią okiem.', 0),
(9134, 'plPL', 'Ojej, ta skrzynia z towarami wygląda na ciężką! Chcesz ją załadować na jedną z moich latających ślicznotek?', 0),
(9135, 'plPL', '$N, już z powrotem? Czy to te towary, po które cię posłałam? Niemożliwe, żeby to było wszystko, o co prosiłam!', 0),
(9328, 'plPL', 'Szukasz u mnie posłuchania, $N? Nie przypominam sobie, by ktoś cię zapowiadał.', 0),
(9489, 'plPL', 'Czy $gtchnąłeś:tchnęłaś; nadzieję tam, gdzie zaczynała gasnąć?', 0),
(9618, 'plPL', 'Udało ci się odnaleźć Keltusa?', 0),
(9619, 'plPL', 'Czy $gpodążyłeś:podążyłaś; ścieżką, którą ukazał ci kamień pustki?', 0),
(9678, 'plPL', 'Niech Światło ugina się przed twoją wolą we wszystkim, czego się podejmiesz.', 0),
(9684, 'plPL', 'Czy $grozmawiałeś:rozmawiałaś; z magistrem Astalorem Krwioprzysięgłym?', 0),
(9686, 'plPL', 'Krwawy Rycerz prędzej zginie, niż podda się wrogowi. Pamiętaj o tym, $N.', 0),
(9692, 'plPL', 'Czy $gzrobiłeś:zrobiłaś; wszystko, o co cię poproszono?', 0),
(9707, 'plPL', 'Gratulacje, $N. Osiągnięcie rangi adepta to nie byle co, wierz mi. Widziałem, ilu wchodzi do tamtego budynku i jak niewielu wytrzymuje dość długo, by przyjść do mnie z tymi materiałami.', 0),
(9723, 'plPL', 'Czy $gwróciłeś:wróciłaś; z materiałami, których potrzebuje magister Astalor?', 0),
(9725, 'plPL', 'Witaj z powrotem, $N. $GOdparłeś:Odparłaś; Plagę i jej wozy z mięsem?', 0),
(9735, 'plPL', 'Udało ci się zdobyć wodę?', 0),
(9736, 'plPL', '$GZebrałeś:Zebrałaś; odczynniki, których potrzebuję?', 0),
(9737, 'plPL', 'Czy $gzrobiłeś:zrobiłaś;, o co prosiłem, i $gprzekazałeś:przekazałaś; moją wiadomość? Fałszywi paladyni tego świata muszą już wiedzieć, że ich czas dobiegł końca.', 0),
(9811, 'plPL', 'Szukasz u mnie posłuchania? Nie przypominam sobie, by ktoś cię zapowiadał.', 0);
