(23732, 'plPL', 'Kamień pustki', '', 0),
(23919, 'plPL', 'Plik raportów', 'Wszystkie raporty podpisał Keltus Mroczny Liść.', 0),
(23924, 'plPL', 'Szata Srebrnej Luny', '', 0),
(24156, 'plPL', 'Napełnione lśniące naczynie', 'Naczynie wypełnia dziwny płyn promieniujący świętą mocą.', 0),
(24157, 'plPL', 'Lśniące naczynie', 'Delikatny pojemnik z materiału, którego nie sposób rozpoznać.', 0),
(24184, 'plPL', 'Napełnione lśniące naczynie', 'Naczynie wypełnia dziwny płyn promieniujący świętą mocą.', 0),
(24223, 'plPL', 'Notatki Krwawego Męstwa', 'Odręczne instrukcje rycerza-lorda Krwawe Męstwo dla kandydatów do rangi adepta Krwawych Rycerzy.', 0),
(24224, 'plPL', 'Skrzynia krwawokutych sztab', 'Skrzynia pełna sztab ciemnego metalu, od których bije wrażenie, że coś jest z nimi nie tak.', 0),
(24225, 'plPL', 'Krew gniewnych', 'Zakorkowana flaszka silnej demonicznej krwi, idealnej do hartowania świeżo wykutej broni Krwawego Rycerza.', 0),
(24226, 'plPL', 'Insygnium Krwawych Rycerzy', 'Mały wisior z czarno-czerwonego emaliowanego metalu w kształcie sokoła.', 0),
(24239, 'plPL', 'Skrzynia z materiałami', '', 0),
(24277, 'plPL', 'Przedmioty dla magistra Astalora Krwioprzysięgłego', 'Lista przedmiotów i surowców potrzebnych magistrowi Astalorowi Krwioprzysięgłemu', 0),
(24284, 'plPL', 'Woda święcona z Dłoni Tyra', 'Fiolka z próbką wody święconej z opactwa Szkarłatnej Krucjaty w Dłoni Tyra.', 0),
(24285, 'plPL', 'Proszek zmierzchu', 'Ten ciemny proszek chętnie pochłania światło.', 0),
(24286, 'plPL', 'Tajemny katalizator', 'Jaskrawo zabarwiony proszek ułatwiający reakcje między substancjami magicznymi.', 0),
(24287, 'plPL', 'Mieszanka gasząca', 'Lśniący, atramentowo czarny płyn, który potrafi zgasić wieczny płomień.', 0),
(25464, 'plPL', 'Korseka hartowana krwią', '', 0),
(25549, 'plPL', 'Tabard Krwawych Rycerzy', '', 0),
(27685, 'plPL', 'Przepis: stek z rysia', 'Uczy przyrządzania steku z rysia.', 0),
(29583, 'plPL', 'Złowieszczy sejmitar', '', 0),
(29584, 'plPL', 'Przebijacze gardeł', '', 0),
(49943, 'plPL', 'Urocza kartka ze Srebrnej Luny', 'Od lorda regenta Quel\'Thalas, Lor\'themara Therona.', 0);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2930, 'plPL', '$N,\n\nWykonanie korseki hartowanej krwią wymaga wielu rzadkich i niestabilnych materiałów, a jego owocem jest groźna broń najwyższej próby. Wymienię materiały w kolejności od najłatwiejszego do najtrudniejszego do zdobycia.\n\nNie zapominaj, że musisz też zdobyć insygnium Krwawych Rycerzy, zanim materiały zostaną przyjęte i będzie można rozpocząć wykuwanie.', 0),
(2931, 'plPL', 'Krew gniewnych – aby właściwie zahartować metal twojej broni, trzeba go schłodzić we krwi gniewnych. Choć krew większości demonów kryje w sobie sporą moc, zwykła krew nie wystarczy do wykucia twojej korseki.\n\nDyskretne rozpytywanie wśród czarnoksiężników Orgrimmaru pomogło ustalić, gdzie można zdobyć tę krew. Kultyści Palącego Ostrza w Rozpadlinie Wściekłego Ognia mają kulę wypełnioną krwią, jakiej potrzebujemy do twojej broni. Podobno kuli strzeże ork, który każe się nazywać Jergoshem Inwokatorem.\n\nZachowaj ostrożność, jak zawsze w kontaktach z demonicznymi mocami. Nigdy nie wiadomo, co może się wydarzyć, gdy ma się do czynienia z tak potężną substancją.', 0),
(2932, 'plPL', 'Skrzynia krwawokutych sztab – stal sama w sobie jest dobrym metalem, lecz wykuta z niej broń niczym się nie wyróżnia. Krwawokute sztaby to materiał o wiele lepszy, wytwarzany w procesie, który pozostaje pilnie strzeżoną tajemnicą. Plotka głosi, że każdego kowala dość śmiałego, by dotknąć tego metalu i go obrabiać, dosięga klątwa, lecz nasi rzemieślnicy dowiedli, że to nieprawda.\n\nZła sława metalu sprawia, że trudno go zdobyć, ale Porzuceni donieśli, że pewien zapas może się znajdować w Twierdzy Cienistego Kła. Wprawny kowal nazwiskiem Landen Stilwell był na tyle ciekaw, że przemycił do twierdzy skrzynię sztab. Nie wiadomo, gdzie Stilwell ukrył swój skarb, ale nasz informator twierdzi, że kowal jest więziony w lochu twierdzy. Użyj wszelkich dostępnych środków, by zdobyć sztaby.', 0),
(2933, 'plPL', 'Skażony klejnot Kor – według ksiąg magistrów niektórzy czarodzieje używają tych klejnotów do gromadzenia energii dla swojej magii, co czyni ją jeszcze groźniejszą. Choć oczyszczone odmiany klejnotu mogą bezpiecznie stosować początkujący czarodzieje, są one zbyt słabe do naszych celów.\n\nW jaskiniach Czarnych Głębin nagi władające magią nasyciły klejnoty Kor własną mroczną mocą i wzmocniły je w sposób, który czyni je idealnymi dla twojej korseki. Zabijaj je bez litości, dopóki nie zdobędziesz potrzebnego klejnotu.', 0),
(2934, 'plPL', 'Insygnium, które będziesz nosić jako $gadept:adeptka;, ostatnio nosił dzielny i nieustraszony Krwawy Rycerz z rodu Gwiazdy Zarannej. Jego wzorowa służba to dobry omen dla twojego własnego życia w zakonie.\n\nKrwawy Rycerz Gwiazda Zaranna poprowadził śmiały, lecz nieudany atak na twierdzę Plagi – Ostoję Śmierci. Jego ciało spoczywa tam, gdzie zginął, zwarty w walce z naszymi największymi wrogami. Odnajdź go, $N, i przynieś mi jego insygnium. Twój sukces przyniesie chwałę jemu, tobie i wszystkim prawdziwym Krwawym Rycerzom.', 0),
(2941, 'plPL', 'Lady Liadrin,$B$BNiedawne kłopoty z uwięzioną istotą uszkodziły część naszego najważniejszego wyposażenia. Przywrócenie nad nią kontroli nadmiernie nadwyrężyło zarówno moich magistrów, jak i nasze zasoby. Złożyłem raporty o tym zdarzeniu Wielkiemu Magistrowi Rommathowi, lecz nie spieszy się on z odpowiedzią. Obawiam się, że bez poniższych materiałów będziemy zmuszeni ograniczyć nasze działania, a dobrze wiesz, co by to oznaczało dla twoich rycerzy.$B$BJeśli możesz w jakikolwiek sposób pomóc, na następnej stronie załączam listę materiałów. Będę niezmiernie wdzięczny za wszelkie wsparcie, jakiego może udzielić twój zakon.$B$BMagister Astalor Krwioprzysięgły', 0),
(2942, 'plPL', '* 40 sztuk runicznej tkaniny$B$B* 6 sztabek arkanitu$B$B* 10 pęków słonecznej trawy$B$B* 5 mrocznych run$B$B* 150 sztuk złota', 0);
