INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(12079, 'plPL', '', 'Kolejny uroczo ponury dzień w Trankwillienie, nie sądzisz, $N?$B$BCzym mogę służyć?', 0),
(12081, 'plPL', 'Nie ma większej wolności niż szybowanie po niebie, $N. Czym mogę dziś służyć?', '', 0),
(12083, 'plPL', 'Witaj, przyjacielu. Czym mogę ci dziś służyć?', '', 0),
(12084, 'plPL', '', 'Wybierasz się dziś do Trankwillienu, $N, czy mogę ci pomóc w czymś innym?', 0),
(12085, 'plPL', 'Tak, chcę wykupić lot na Widmowe Ziemie.', 'Tak, chcę wykupić lot na Widmowe Ziemie.', 0),
(12395, 'plPL', 'Nie widzisz, że próbuję porozmawiać z damą? No dobrze, i tak wydaje się zajęta czymś innym.$B$BHandluję wyłącznie najprzedniejszymi trunkami, zarówno miejscowymi, jak i egzotycznymi rocznikami. Zechcesz rzucić okiem?', '', 0),
(12528, 'plPL', 'Daję schronienie, jakie tylko mogę, w naszej zdruzgotanej krainie.', 'Daję schronienie, jakie tylko mogę, w naszej zdruzgotanej krainie.', 0),
(12823, 'plPL', 'Przestrzegaj prawa!', '', 0),
(12824, 'plPL', 'Służba dla dobra publicznego!', '', 0),
(12832, 'plPL', 'Chyba wybiorę się na łowy na tego Nędznego, skoro wyznaczono nagrodę za jego głowę.', '', 0),
(12835, 'plPL', 'Błagam! Muszę się czymś wkrótce pożywić... Kryształ many... odłamek... cokolwiek! Ten ból jest nie do zniesienia!', '', 0),
(13167, 'plPL', 'Niewiele pojedynków wygrywa się samą siłą. Ostatecznie o zwycięstwie decydują spryt, refleks i znajomość własnej broni.', 'Niewiele pojedynków wygrywa się samą siłą. Ostatecznie o zwycięstwie decydują spryt, refleks i znajomość własnej broni.', 0),
(13168, 'plPL', 'Pokaż mi, co umiesz, Larenisie.', 'Pokaż mi, co umiesz, Larenisie.', 0),
(13697, 'plPL', 'Widmowych Ziem nie odzyskamy samą siłą oręża, $N. Tu właśnie wkraczamy my, magistrowie.$B$BNasza przebiegłość i znajomość magii tajemnej nie mają sobie równych.', '', 0),
(14189, 'plPL', '', '<Eralan zdaje się przeżuwać trochę trupiego ziela.>$b$bJeśli chcesz uwarzyć eliksir miłosny, $gtrafiłeś:trafiłaś; pod zły adres. Oślepianie, okaleczanie i zabijanie to mój fach, a miejmy nadzieję, że i twój.', 0),
(14215, 'plPL', '', 'Witaj w Rejestrze Gildii. Czym mogę ci służyć?', 0),
(14365, 'plPL', 'Broń się, młokosie! Zobaczymy, czy drzemie w tobie Krwawy Rycerz.', '', 0),
(14367, 'plPL', 'To... Srebrna Luna? Moja głowa... Następnym razem, gdy Krwawe Męstwo będzie szukał ochotnika, wskażę mu kogoś innego. Wzór cnót Krwawego Rycerza, akurat!', '', 0),
(14368, 'plPL', 'Nie zrozum mnie źle, $N. Bardzo doceniam wskrzeszenie, ale chyba ostatni raz pełniłem tę konkretną powinność. Może kielich czy dwa wina pomogą na ten ból głowy.', '', 0),
(14435, 'plPL', 'Dzień dobry, $N. Jeśli pragniesz poznać sztukę kowalską, $gtrafiłeś:trafiłaś; we właściwe miejsce.', '', 0),
(14436, 'plPL', 'Chcę się szkolić na kowala.', 'Chcę się szkolić na kowala.', 0),
(14459, 'plPL', 'Niech rozpocznie się próba! Krwawy Gniewie, atakuj!', '', 0),
(14460, 'plPL', 'Czempionie Rozdzieraczu Światła, przynieś mi chlubę!', '', 0),
(14462, 'plPL', 'Pokaż temu żółtodziobowi, jak walczy prawdziwy Krwawy Rycerz, Chyże Ostrze!', '', 0),
(14463, 'plPL', 'Słońcobiju, niech $N pozna, co znaczy ból!', '', 0),
(14464, 'plPL', 'Dobra robota, $N! $GPrzeszedłeś:Przeszłaś; drugą próbę!', '', 0),
(14730, 'plPL', 'Witaj w siedzibie Krwawych Rycerzy – obrońców Quel\'Thalas, wiernych sług Srebrnej Luny i prawdziwych mistrzów Światła.', '', 0),
(14782, 'plPL', 'Szczęście jest obowiązkowe, $gobywatelu:obywatelko;.', '', 0),
(14783, 'plPL', 'Przestrzegaj praw Srebrnej Luny. Niepodporządkowanie się skutkuje eliminacją.', '', 0),
(14784, 'plPL', 'Trwajcie w sile. Kael\'thas poprowadzi – błąd – Lor\'themar poprowadzi was ku potędze i chwale!', '', 0),
(14785, 'plPL', 'Nie zakłócaj spokoju miasta. Pokój musi być utrzymany.', '', 0),
(14787, 'plPL', 'Utrzymuj porządek w tych murach.', '', 0),
(14791, 'plPL', 'Nasze życie należy do ciebie, Krwawy Rycerzu.', 'Nasze życie należy do ciebie, Krwawy Rycerzu.', 0),
(14792, 'plPL', 'Twoja moc wzmacnia nas wszystkich.', 'Twoja moc wzmacnia nas wszystkich.', 0),
(14793, 'plPL', 'Nawet Światło nie dorówna niezłomnej woli naszego ludu.', 'Nawet Światło nie dorówna niezłomnej woli naszego ludu.', 0),
(14807, 'plPL', 'Chwała Królowi Słoń... ech... Srebrnej Lunie!', 'Chwała Królowi Słoń... ech... Srebrnej Lunie!', 0),
(14808, 'plPL', '%s unosi wyrzeźbioną brew, spoglądając na strażników z wyraźną dezaprobatą.', '%s unosi wyrzeźbioną brew, spoglądając na strażników z wyraźną dezaprobatą.', 0),
(14809, 'plPL', '%s przenosi wzrok z jednego strażnika na drugiego.', '%s przenosi wzrok z jednego strażnika na drugiego.', 0),
(14810, 'plPL', '%s z protekcjonalnym uśmieszkiem lustruje niewielki plac ćwiczeń tropicieli.', '%s z protekcjonalnym uśmieszkiem lustruje niewielki plac ćwiczeń tropicieli.', 0),
(14811, 'plPL', '%s lekko skłania głowę przed parą strażników na powitanie.', '%s lekko skłania głowę przed parą strażników na powitanie.', 0),
(14815, 'plPL', 'Nasi sąsiedzi są wprost śmieszni. Widziałeś, jak zadzierają przed nami nosa?', 'Nasi sąsiedzi są wprost śmieszni. Widziałeś, jak zadzierają przed nami nosa?', 0),
(14818, 'plPL', 'Tropiciele z pewnością mają o sobie wysokie mniemanie.', 'Tropiciele z pewnością mają o sobie wysokie mniemanie.', 0),
(14819, 'plPL', 'Coraz bardziej męczy mnie wyniosłość, z jaką traktują mnie ci umorusani łucznicy na zewnątrz.', 'Coraz bardziej męczy mnie wyniosłość, z jaką traktują mnie ci umorusani łucznicy na zewnątrz.', 0),
(14820, 'plPL', 'Za kogo oni się mają?', 'Za kogo oni się mają?', 0),
(14821, 'plPL', 'Wiem, o czym mówisz... szepczą o nas, kiedy myślą, że nie słyszymy. Jeszcze dostaną za swoje.', 'Wiem, o czym mówisz... szepczą o nas, kiedy myślą, że nie słyszymy. Jeszcze dostaną za swoje.', 0),
(14822, 'plPL', 'Zazdroszczą, i tyle. Boją się poświęcić prawdziwej potędze.', 'Zazdroszczą, i tyle. Boją się poświęcić prawdziwej potędze.', 0),
(14823, 'plPL', 'Po prostu boją się tego, czego nie są w stanie nawet zacząć pojmować.', 'Po prostu boją się tego, czego nie są w stanie nawet zacząć pojmować.', 0),
(14831, 'plPL', 'Wszystko jest tak niepewne, odkąd komnata na dole stoi pusta...', 'Wszystko jest tak niepewne, odkąd komnata na dole stoi pusta...', 0),
(14833, 'plPL', 'Zniknęło. Nie mogę uwierzyć, że zniknęło. Kto by pomyślał, że ktoś nas tak zdradzi?', 'Zniknęło. Nie mogę uwierzyć, że zniknęło. Kto by pomyślał, że ktoś nas tak zdradzi?', 0),
(14838, 'plPL', 'Lady Liadrin na pewno znajdzie sposób. Musi.', 'Lady Liadrin na pewno znajdzie sposób. Musi.', 0),
(14839, 'plPL', 'Czy to... prawda, co słyszałem? Że to był sam Król Słońca?', 'Czy to... prawda, co słyszałem? Że to był sam Król Słońca?', 0),
(14840, 'plPL', 'Mimo to Krwawi Rycerze przetrwają tę stratę. Nie mamy wyboru... musimy znaleźć inne źródło.', 'Mimo to Krwawi Rycerze przetrwają tę stratę. Nie mamy wyboru... musimy znaleźć inne źródło.', 0),
(15010, 'plPL', '', 'Nie, nie, nie! Wracaj tutaj!', 0),
(15011, 'plPL', '', 'Magister mnie zabije...', 0),
(15012, 'plPL', '', 'Wracaj tu, ty mały...', 0),
(15013, 'plPL', '', 'Argh. Mówili mi, że te kryształy będą działać jak należy!', 0),
(15014, 'plPL', '', 'Tylko nie wchodź w drogę lordowi regentowi! Mówię poważnie!', 0),
(15015, 'plPL', '', 'Jak cię złapię, to odczaruję cię na części, słowo daję...', 0),
(15207, 'plPL', 'Dokąd w naszym pięknym mieście pragniesz się udać?', 'Dokąd w naszym pięknym mieście pragniesz się udać?', 0),
(15209, 'plPL', 'W Srebrnej Lunie mamy dwa domy aukcyjne. Który wolisz?', 'W Srebrnej Lunie mamy dwa domy aukcyjne. Który wolisz?', 0),
(15210, 'plPL', 'Ten na zachodzie.', 'Ten na zachodzie.', 0),
(15211, 'plPL', 'Zachodni dom aukcyjny znajdziesz pośrodku Targowiska, tuż na zachód od Bulwaru Przodków.', 'Zachodni dom aukcyjny znajdziesz pośrodku Targowiska, tuż na zachód od Bulwaru Przodków.', 0),
(15212, 'plPL', 'Ten na wschodzie.', 'Ten na wschodzie.', 0),
(15213, 'plPL', 'Dom aukcyjny Królewskiej Giełdy znajdziesz we wschodniej części miasta, tuż na południe od placu ćwiczeń Krwawych Rycerzy i tropicieli.', 'Dom aukcyjny Królewskiej Giełdy znajdziesz we wschodniej części miasta, tuż na południe od placu ćwiczeń Krwawych Rycerzy i tropicieli.', 0),
(15216, 'plPL', 'Na zachodzie.', 'Na zachodzie.', 0),
(15217, 'plPL', 'Bank Srebrnej Luny znajduje się na Targowisku. Szukaj go w południowo-wschodnim narożniku.', 'Bank Srebrnej Luny znajduje się na Targowisku. Szukaj go w południowo-wschodnim narożniku.', 0),
(15218, 'plPL', 'Na wschodzie.', 'Na wschodzie.', 0),
(15219, 'plPL', 'Jeśli szukasz banku we wschodniej części miasta, nie szukaj dalej niż w Królewskiej Giełdzie. Bank leży tam przy północnym murze.', 'Jeśli szukasz banku we wschodniej części miasta, nie szukaj dalej niż w Królewskiej Giełdzie. Bank leży tam przy północnym murze.', 0),
(15221, 'plPL', 'Mistrzyni lotów Zmierzch i jej smocze jastrzębie są tuż za Bramą Pasterza, po zachodniej stronie.', 'Mistrzyni lotów Zmierzch i jej smocze jastrzębie są tuż za Bramą Pasterza, po zachodniej stronie.', 0),
(15223, 'plPL', 'Tandrine jest mistrzynią gildii Srebrnej Luny. Jej rezydencja leży przy Bulwarze Przodków, blisko Bramy Magistrów.', 'Tandrine jest mistrzynią gildii Srebrnej Luny. Jej rezydencja leży przy Bulwarze Przodków, blisko Bramy Magistrów.', 0),
(15225, 'plPL', 'Karczmę Srebrnej Luny w Królewskiej Giełdzie prowadzi utalentowana kobieta imieniem Velandra. Podobno czasem bywa tam także słynny mistrz winnic.', 'Karczmę Srebrnej Luny w Królewskiej Giełdzie prowadzi utalentowana kobieta imieniem Velandra. Podobno czasem bywa tam także słynny mistrz winnic.', 0),
(15227, 'plPL', 'W naszym pięknym mieście nie brakuje skrzynek pocztowych. Ta przy Banku Królewskiej Giełdy z pewnością zaspokoi twoje potrzeby.', 'W naszym pięknym mieście nie brakuje skrzynek pocztowych. Ta przy Banku Królewskiej Giełdy z pewnością zaspokoi twoje potrzeby.', 0),
(15229, 'plPL', 'Shalenn dogląda zwierząt w mieście i pilnuje, by nie szalały, podczas gdy ich właściciele dalej trwonią życie na błahostki. Stoi na Skwerze Obieżyświatów, tuż przed siedzibą tropicieli.', 'Shalenn dogląda zwierząt w mieście i pilnuje, by nie szalały, podczas gdy ich właściciele dalej trwonią życie na błahostki. Stoi na Skwerze Obieżyświatów, tuż przed siedzibą tropicieli.', 0),
(15231, 'plPL', 'Krwawi Rycerze na Skwerze Obieżyświatów łaskawie użyczają miejsca w swoich salach Iledzie, mistrzyni broni Srebrnej Luny. Jej nauki nie są tanie, ale docenisz jej biegłość.', 'Krwawi Rycerze na Skwerze Obieżyświatów łaskawie użyczają miejsca w swoich salach Iledzie, mistrzyni broni Srebrnej Luny. Jej nauki nie są tanie, ale docenisz jej biegłość.', 0),
(15233, 'plPL', 'Mistrzowie bitewni odpoczywają w głębi sal enklawy Krwawych Rycerzy na Skwerze Obieżyświatów. Choć są nieco... prostaccy, mają też swoje zalety.', 'Mistrzowie bitewni odpoczywają w głębi sal enklawy Krwawych Rycerzy na Skwerze Obieżyświatów. Choć są nieco... prostaccy, mają też swoje zalety.', 0),
(15237, 'plPL', 'Druidów? Nasz lud nie kroczy tą ścieżką... ale masz szczęście. Pewna taurenka – przynajmniej sądzę, że to kobieta – urządziła sobie skromne mieszkanie na północnym krańcu Bulwaru Przodków. Nazywa się Harene Wędrowczyni Równin.\n', 'Druidów? Nasz lud nie kroczy tą ścieżką... ale masz szczęście. Pewna taurenka – przynajmniej sądzę, że to kobieta – urządziła sobie skromne mieszkanie na północnym krańcu Bulwaru Przodków. Nazywa się Harene Wędrowczyni Równin.', 0),
(15239, 'plPL', 'Och. Szukasz jednego z... nich. Cóż, jeśli naprawdę chcesz tracić czas na rozmowy z tymi zacofańcami, tropicieli znajdziesz na Skwerze Obieżyświatów. Zandine się tobą zajmie.', 'Och. Szukasz jednego z... nich. Cóż, jeśli naprawdę chcesz tracić czas na rozmowy z tymi zacofańcami, tropicieli znajdziesz na Skwerze Obieżyświatów. Zandine się tobą zajmie.', 0),
(15245, 'plPL', 'Ach, szukasz mistrzów magii tajemnej? Quithasa i pozostałych magistrów znajdziesz w Iglicy Słonecznej Furii.', 'Ach, szukasz mistrzów magii tajemnej? Quithasa i pozostałych magistrów znajdziesz w Iglicy Słonecznej Furii.', 0),
(15246, 'plPL', 'Lady Liadrin, matriarcha Krwawych Rycerzy, ma siedzibę zakonu w enklawie na Skwerze Obieżyświatów. Jeśli szukasz nauki, porozmawiaj tam z czempionem Bachim. I zachowuj się z szacunkiem, jeśli ci życie miłe.', 'Lady Liadrin, matriarcha Krwawych Rycerzy, ma siedzibę zakonu w enklawie na Skwerze Obieżyświatów. Jeśli szukasz nauki, porozmawiaj tam z czempionem Bachim. I zachowuj się z szacunkiem, jeśli ci życie miłe.', 0),
(15247, 'plPL', 'Kapłanów naszego pięknego miasta znajdziesz w Iglicy Słonecznej Furii. Odszukaj panią Belestrę.', 'Kapłanów naszego pięknego miasta znajdziesz w Iglicy Słonecznej Furii. Odszukaj panią Belestrę.', 0),
(15248, 'plPL', 'Zręczniejszych spośród nas bywa trudno wypatrzyć, niemniej łotra Zelanisa i jego kompanów spotkasz zapewne w głębi Morderczego Zgiełku.', 'Zręczniejszych spośród nas bywa trudno wypatrzyć, niemniej łotra Zelanisa i jego kompanów spotkasz zapewne w głębi Morderczego Zgiełku.', 0),
(15249, 'plPL', 'Przywoływanie demonów to niebezpieczna praktyka, lecz zdobyta w ten sposób moc bywa ogromna. Naszą miejscową znawczynią jest Alamma, która czuwa nad czarnoksiężnikami w Morderczym Zgiełku.', 'Przywoływanie demonów to niebezpieczna praktyka, lecz zdobyta w ten sposób moc bywa ogromna. Naszą miejscową znawczynią jest Alamma, która czuwa nad czarnoksiężnikami w Morderczym Zgiełku.', 0),
(15254, 'plPL', 'Alchemicy przebywają na Dziedzińcu Słońca; Camberon chętnie nauczy cię wszystkiego, co zechcesz wiedzieć o sztuce warzenia mikstur.', 'Alchemicy przebywają na Dziedzińcu Słońca; Camberon chętnie nauczy cię wszystkiego, co zechcesz wiedzieć o sztuce warzenia mikstur.', 0),
(15256, 'plPL', 'Kowalstwa naucza Bemarrin na Skwerze Obieżyświatów. Choć to rzemiosło nieco... brudne, przypuszczam, że ma swoje zalety.', 'Kowalstwa naucza Bemarrin na Skwerze Obieżyświatów. Choć to rzemiosło nieco... brudne, przypuszczam, że ma swoje zalety.', 0),
(15258, 'plPL', 'Zaklinaczka Sedana przyjmuje obecnie uczniów, jak sądzę. Znajdziesz ją w jednej z wnęk na Dziedzińcu Słońca.', 'Zaklinaczka Sedana przyjmuje obecnie uczniów, jak sądzę. Znajdziesz ją w jednej z wnęk na Dziedzińcu Słońca.', 0),
(15260, 'plPL', 'Dziwny wybór... ale nie mnie oceniać. Szukasz Danwe; jej stanowisko inżynierskie stoi przy Dziedzińcu Słońca, na ścieżce do Skweru Obieżyświatów.', 'Dziwny wybór... ale nie mnie oceniać. Szukasz Danwe; jej stanowisko inżynierskie stoi przy Dziedzińcu Słońca, na ścieżce do Skweru Obieżyświatów.', 0),
(15262, 'plPL', 'Alestus jest mistrzem tej... bardziej brudnej metody opatrywania ran. Jeśli chcesz nauczyć się pierwszej pomocy, szukaj go przy Bulwarze Przodków, w pobliżu wejścia do Królewskiej Giełdy.', 'Alestus jest mistrzem tej... bardziej brudnej metody opatrywania ran. Jeśli chcesz nauczyć się pierwszej pomocy, szukaj go przy Bulwarze Przodków, w pobliżu wejścia do Królewskiej Giełdy.', 0),
(15264, 'plPL', 'Wody Quel\'Thalas roją się od ryb; rozumiem, że wpadły ci w oko? Drathen zna wszystkie sztuczki wędkarskiego fachu. Znajdziesz go przy Bulwarze Przodków, w pobliżu Królewskiej Giełdy.', 'Wody Quel\'Thalas roją się od ryb; rozumiem, że wpadły ci w oko? Drathen zna wszystkie sztuczki wędkarskiego fachu. Znajdziesz go przy Bulwarze Przodków, w pobliżu Królewskiej Giełdy.', 0),
(15266, 'plPL', 'Botaniczka Nathera ma bystre oko do szukania ziół i przypuszczam, że podzieli się swoją mądrością nawet z kimś takim jak ty. Znajdziesz ją wśród alchemików, we wnęce na Dziedzińcu Słońca.', 'Botaniczka Nathera ma bystre oko do szukania ziół i przypuszczam, że podzieli się swoją mądrością nawet z kimś takim jak ty. Znajdziesz ją wśród alchemików, we wnęce na Dziedzińcu Słońca.', 0),
(15268, 'plPL', 'Jeśli interesuje cię jubilerstwo, sklep Kalindy znajdziesz na południowym krańcu Królewskiej Giełdy.', 'Jeśli interesuje cię jubilerstwo, sklep Kalindy znajdziesz na południowym krańcu Królewskiej Giełdy.', 0),
(15270, 'plPL', 'Przy południowo-wschodnim krańcu Bulwaru Przodków Lynalis urządziła porządne stanowisko garbarskie. Wyszkoli cię... za opłatą.', 'Przy południowo-wschodnim krańcu Bulwaru Przodków Lynalis urządziła porządne stanowisko garbarskie. Wyszkoli cię... za opłatą.', 0),
(15272, 'plPL', 'Jeśli grzebanie w ziemi to rozrywka, która sprawia ci przyjemność, idź podzielić się swoim szaleństwem z Belilem na Skwerze Obieżyświatów. Z pewnością ucieszy się, że nie tylko on jest tu szalony.', 'Jeśli grzebanie w ziemi to rozrywka, która sprawia ci przyjemność, idź podzielić się swoim szaleństwem z Belilem na Skwerze Obieżyświatów. Z pewnością ucieszy się, że nie tylko on jest tu szalony.', 0),
(15274, 'plPL', 'Tyn to niezwykle utalentowana skórniczka; wyprawia najwspanialsze rysie skóry, jakie kiedykolwiek widziano. Jeśli chcesz się od niej uczyć, znajdziesz ją na południowo-wschodnim krańcu Bulwaru Przodków.', 'Tyn to niezwykle utalentowana skórniczka; wyprawia najwspanialsze rysie skóry, jakie kiedykolwiek widziano. Jeśli chcesz się od niej uczyć, znajdziesz ją na południowo-wschodnim krańcu Bulwaru Przodków.', 0),
(15276, 'plPL', 'Krawiec Keelen wciąż szuka ciekawych uczniów, którym mógłby przekazać swoje delikatne rzemiosło. Jego sklep z początku trudno odnaleźć, ale leży tuż na północ od domu aukcyjnego na Targowisku. Znajdziesz go na dolnym poziomie budynku.', 'Krawiec Keelen wciąż szuka ciekawych uczniów, którym mógłby przekazać swoje delikatne rzemiosło. Jego sklep z początku trudno odnaleźć, ale leży tuż na północ od domu aukcyjnego na Targowisku. Znajdziesz go na dolnym poziomie budynku.', 0),
(15673, 'plPL', '', 'Bracia i siostry. Posłuchajcie mnie. Musimy pomówić o przetrwaniu naszego ludu. Ledwie przetrwaliśmy jedną katastrofę, lecz obawiam się, że następna nas zgładzi.', 0),
(15674, 'plPL', '', 'Czy nie widzicie, co się dzieje? Otwórzcie oczy. Wszystko leży jak na dłoni. Czym jest ten nowy sojusz? Dlaczego zdradziliśmy dawnych sprzymierzeńców, tylko po to, by zbratać się z wrogami wszystkiego, co żyje?', 0),
(15675, 'plPL', 'Nie, mylisz się! To nas zdradzono!', '', 0),
(15676, 'plPL', 'A kiedy to krasnoludy były naszymi przyjaciółmi?', '', 0),
(15677, 'plPL', '', 'Ludzie porzucili nas w najczarniejszej godzinie! Ich własny książę poprowadził natarcie na nasze ziemie.', 0),
(15678, 'plPL', 'Głupcze! Sługami księcia byli ci sami Porzuceni, z którymi teraz się sprzymierzyliśmy, a teraz on nas zdradził!', '', 0),
(15679, 'plPL', 'Generał tropicieli Srebrnej Luny będzie wiernym sojusznikiem!', '', 0),
(15680, 'plPL', '', 'Mówisz o niej jak o przyjaciółce? Głupiec z ciebie. Ta „Mroczna Pani” to nie Sylwana.', 0),
(15738, 'plPL', 'Krew nie zawiedzie. Możemy ufać tylko swoim!', '', 0),
(15743, 'plPL', '', 'Krew? A te orki, ci przyjaciele od święta? One nam pomogą?', 0),
(15744, 'plPL', 'Wielka zaraza spowija naszą ziemię! Rośnie z każdym dniem. Nasz głód magii osłabia nas i przywiedzie nas do zagłady, tak jak już raz się stało!', '', 0),
(15745, 'plPL', 'Jak mamy żyć bez magii?', '', 0),
(15747, 'plPL', '', 'Spójrzcie na cuda tego miasta! Oto magia.', 0),
(15748, 'plPL', 'Ale jakim kosztem? Wszyscy jesteście zaślepieni. Wszyscy jesteśmy zaślepieni.', '', 0),
(15749, 'plPL', 'Nazywasz nas zdrajcami?', '', 0),
(15750, 'plPL', '', 'To magistrowie są zdrajcami! Przypieczętowali naszą zgubę.', 0),
(15751, 'plPL', 'Idealistyczne brednie. Wracaj do swoich lasów!', '', 0),
(15752, 'plPL', '', 'Chcesz, żebyśmy żyli jak dzicy!', 0),
(15753, 'plPL', 'Nie dzikość! Sumienie. Wybujałe żądze naszego ludu zniszczą nas i wszystko, co z takim trudem zbudowaliśmy.', '', 0),
(15754, 'plPL', '', 'Nie walczyliśmy tak zaciekle o przetrwanie tylko po to, by sprowadzić na siebie prawdziwą zagładę.', 0),
(15756, 'plPL', 'Stoimy na krawędzi zagłady. Musimy się zastanowić nad tym pochopnym kursem.', '', 0),
(15825, 'plPL', 'Czy możecie przestać...', 'Czy możecie przestać...', 0),
(15868, 'plPL', 'Witaj w Banku Królewskiej Giełdy, $gpanie:pani;. Czym mogę służyć?', 'Witaj w Banku Królewskiej Giełdy, $gpanie:pani;. Czym mogę służyć?', 0),
(15869, 'plPL', 'Dziękujemy za wybór Banku Srebrnej Luny. Czym mogę ci dziś służyć?', 'Dziękujemy za wybór Banku Srebrnej Luny. Czym mogę ci dziś służyć?', 0),
(15872, 'plPL', 'Witaj. W czym my, Bank Królewskiej Giełdy, możemy ci dziś pomóc?', 'Witaj. W czym my, Bank Królewskiej Giełdy, możemy ci dziś pomóc?', 0),
(15873, 'plPL', 'Witaj w Banku Srebrnej Luny, $gpanie:pani;. Czy zechcesz skorzystać z depozytu?', 'Witaj w Banku Srebrnej Luny, $gpanie:pani;. Czy zechcesz skorzystać z depozytu?', 0),
(15904, 'plPL', 'Nie ma tu nic do oglądania. Rozejść się.', 'Nie ma tu nic do oglądania. Rozejść się.', 0),
(15905, 'plPL', 'To cię nie dotyczy. Idź swoją drogą.', 'To cię nie dotyczy. Idź swoją drogą.', 0),
(15917, 'plPL', '', 'Jeśli przemówimy jednym głosem, nie da się nas zignorować!', 0),
(15918, 'plPL', 'Użyczcie nam swoich głosów! Teraz jest czas, by działać i ocalić nasz lud.', '', 0),
(15919, 'plPL', 'Lor\'themar musi nas wysłuchać! Nie damy się uciszyć!', '', 0),
(15924, 'plPL', 'Lor\'themar przemienił Srebrną Lunę w coś, z czego możemy być naprawdę dumni.', '', 0),
(15926, 'plPL', 'Magistrowie są mądrzy i wytyczą nam kurs ku pomyślnej przyszłości.', '', 0),
(15930, 'plPL', '', 'Odpłacimy Przymierzu za zdradę! Nigdy nie zapomnimy i nigdy nie wybaczymy!', 0),
(15937, 'plPL', 'Proszę, nic do mnie nie mów. Nie chcę mieć z nimi więcej kłopotów.', 'Proszę, nic do mnie nie mów. Nie chcę mieć z nimi więcej kłopotów.', 0),
(15964, 'plPL', 'Chodzi ci o Karczmę Srebrnej Luny czy o gospodę „Odpoczynek Wędrowca”?', 'Chodzi ci o Karczmę Srebrnej Luny czy o gospodę „Odpoczynek Wędrowca”?', 0),
(15965, 'plPL', 'Gospoda „Odpoczynek Wędrowca”.', 'Gospoda „Odpoczynek Wędrowca”.', 0),
(15966, 'plPL', 'Karczma Srebrnej Luny.', 'Karczma Srebrnej Luny.', 0),
(15967, 'plPL', 'Gospoda „Odpoczynek Wędrowca” leży między Bulwarem Przodków a Targowiskiem. Dojdziesz do niej z obu stron.', 'Gospoda „Odpoczynek Wędrowca” leży między Bulwarem Przodków a Targowiskiem. Dojdziesz do niej z obu stron.', 0),
(16028, 'plPL', 'Sylann, jedną z najlepszych kucharek w mieście, znajdziesz na piętrze gospody „Odpoczynek Wędrowca”. U jej pomocnika kupisz tam także zapasy kucharskie.', 'Sylann, jedną z najlepszych kucharek w mieście, znajdziesz na piętrze gospody „Odpoczynek Wędrowca”. U jej pomocnika kupisz tam także zapasy kucharskie.', 0),
(16058, 'plPL', 'Kłopoty z Nędznymi? Mam dokładnie to, czego ci trzeba.\n', 'Kłopoty z Nędznymi? Mam dokładnie to, czego ci trzeba.\n', 0),
(16059, 'plPL', 'Tylko nie pytaj, skąd to mam...\n', 'Tylko nie pytaj, skąd to mam...\n', 0),
(16091, 'plPL', 'Trzeba coś zrobić z tymi Nędznymi...\n', 'Trzeba coś zrobić z tymi Nędznymi...\n', 0),
(16092, 'plPL', 'Gdy się z nimi rozprawimy, będziemy mogli przeznaczyć więcej sił na wojnę.\n', 'Gdy się z nimi rozprawimy, będziemy mogli przeznaczyć więcej sił na wojnę.\n', 0),
(16093, 'plPL', 'Gdybym tylko miała trochę wina do tego sera...\n', 'Gdybym tylko miała trochę wina do tego sera...\n', 0),
(16094, 'plPL', 'Ach, co za okropna robota!\n', 'Ach, co za okropna robota!\n', 0),
(16095, 'plPL', 'Cały dzień w smrodzie spoconych stóp.\n', 'Cały dzień w smrodzie spoconych stóp.\n', 0),
(16096, 'plPL', 'Godziny mijałyby o wiele słodziej.\n', 'Godziny mijałyby o wiele słodziej.\n', 0),
(16097, 'plPL', 'Czemu matka nie mogła poświęcić się czemuś innemu?\n', 'Czemu matka nie mogła poświęcić się czemuś innemu?', 0),
(16098, 'plPL', 'Ciasta, wypieki, nawet chleb – cokolwiek, byle nie ser!\n', 'Ciasta, wypieki, nawet chleb – cokolwiek, byle nie ser!', 0),
(16171, 'plPL', 'Festiwal księżyca zawsze był ważniejszy dla kaldorei. Wielki festiwal druidów z pewnością trwa w najlepsze.', 'Festiwal księżyca zawsze był ważniejszy dla kaldorei. Wielki festiwal druidów z pewnością trwa w najlepsze.', 0),
(16173, 'plPL', 'Zimowa Uczta zawsze była ludzkim zwyczajem. Dziwnie patrzeć, jak przejmują ją gobliny i orkowie.', 'Zimowa Uczta zawsze była ludzkim zwyczajem. Dziwnie patrzeć, jak przejmują ją gobliny i orkowie.', 0),
(16187, 'plPL', 'Jeśli chcesz naprawdę przeżyć Zimową Ucztę, wybierz się do Orgrimmaru.', 'Jeśli chcesz naprawdę przeżyć Zimową Ucztę, wybierz się do Orgrimmaru.', 0),
(16189, 'plPL', 'Jeśli znajdziesz w Srebrnej Lunie biesiadników Festiwalu Księżyca, mogą cię przenieść do Gaju Luny, żebyś $gmógł:mogła; wziąć udział w obchodach.', 'Jeśli znajdziesz w Srebrnej Lunie biesiadników Festiwalu Księżyca, mogą cię przenieść do Gaju Luny, żebyś $gmógł:mogła; wziąć udział w obchodach.', 0),
(17485, 'plPL', 'Bip!', '', 0),
(17486, 'plPL', 'Hej, ty tam. Chcesz cukierka?', '', 0),
(17581, 'plPL', 'Nareszcie ktoś zszedł ze mną porozmawiać! Chcesz posłuchać moich rymów?', '', 0),
(17582, 'plPL', 'TAK!', 'TAK!', 0),
(17583, 'plPL', 'NIE!', 'NIE!', 0),
(17584, 'plPL', 'Idę sobie ulicą! Patrzę na swe nogi! Liście z drzew spadają, prosto mi pod nogi!', '', 0),
(18307, 'plPL', 'Co? Chcesz podarować tkaninę Srebrnej Lunie?$B$BChodzi ci tylko o szybkobieżcę, prawda? No dobrze, dobrze... wyświadcz miastu tę przysługę, a dopilnuję, by twoja reputacja tutaj wzrosła.', '', 0),
(18801, 'plPL', 'Czy jesteś $ggotów:gotowa; walczyć ze Strażą Gromdardy w Dolinie Alterak, $n?', '', 0),
(18825, 'plPL', '', 'Nieumarli o wolnej woli już teraz walczą z Ligą Aratoru w Kotlinie Aratorskiej. Pomożesz Plugawicielom pokonać ludzi i ich sojuszników z Przymierza?', 0),
(18826, 'plPL', 'Throm\'ka, $n. Wąwóz Wojennej Pieśni potrzebuje bohaterów takich jak ty.', '', 0),
(19425, 'plPL', '', 'Chcesz poznać tajniki jubilerstwa?', 0),
(19431, 'plPL', 'Co chcesz wiedzieć o jubilerstwie?', '', 0),
(19433, 'plPL', '', 'Podzielę się z tobą swoją wiedzą o jubilerstwie.', 0),
(19589, 'plPL', 'Krosno many', 'Krosno many', 0),
(19590, 'plPL', 'W sklepie krawieckim Keelena, w północno-zachodnim narożniku Targowiska, stoi takie krosno, jakie opisujesz.', 'W sklepie krawieckim Keelena, w północno-zachodnim narożniku Targowiska, stoi takie krosno, jakie opisujesz.', 0),
(20626, 'plPL', '', 'Nie rozumiem, po co chcesz uczyć się czegoś innego... ale mogę wskazać ci właściwy kierunek. Jakiego dokładnie szkolenia szukasz?', 0),
(20627, 'plPL', '', 'Jeśli nie $gprzyszedłeś:przyszłaś; się szkolić, odsuń się i pozwól mi pracować.', 0),
(21128, 'plPL', '', 'Do rzeczy, $N. Pokażę ci, co umiem, ale nie zostawaj w tyle.', 0),
(21278, 'plPL', 'Witaj w sklepie „Rzetelne krawiectwo Keelena”. Myślę, że mój sklep spełni twoje oczekiwania. Jeśli chcesz się u mnie szkolić, wystarczy poprosić; z największą przyjemnością cię nauczę.', '', 0),
(21686, 'plPL', '', 'Jakie tajemnice rzemiosła mogę ci dziś pomóc odkryć?', 0),
(21691, 'plPL', 'No chodź, chodź. Jeśli choć raz porządnie $gprzygotowałeś:przygotowałaś; skórę, pokażę ci, jak robić z niej użyteczne rzeczy.', 'No chodź, chodź. Jeśli choć raz porządnie $gprzygotowałeś:przygotowałaś; skórę, pokażę ci, jak robić z niej użyteczne rzeczy.', 0),
(21722, 'plPL', 'Podejdź bliżej. Jaka formuła cię dziś interesuje?', 'Podejdź bliżej. Jaka formuła cię dziś interesuje?', 0),
(22399, 'plPL', 'NIE!', 'NIE!', 0),
(22512, 'plPL', 'Jakie zaklęcia cię dziś interesują, $N?', '', 0),
(22513, 'plPL', '', 'Może pokazać ci dziś jakiś wykrój czy dwa?', 0),
(23254, 'plPL', 'Mroczne czasy rodzą dziwne przyjaźnie. Może warto odwiedzić stary Lordaeron i popatrzeć, jak Porzuceni palą swojego wiklinowego ludzika.', 'Mroczne czasy rodzą dziwne przyjaźnie. Może warto odwiedzić stary Lordaeron i popatrzeć, jak Porzuceni palą swojego wiklinowego ludzika.', 0),
(23288, 'plPL', 'Ta pora roku jest bardzo ważna dla naszych sojuszników, Porzuconych.', 'Ta pora roku jest bardzo ważna dla naszych sojuszników, Porzuconych.', 0),
(23356, 'plPL', 'Spójrz na moją zwariowaną twarz z mackami i rozpaczaj, mieszkańcu Azeroth!', 'Spójrz na moją zwariowaną twarz z mackami i rozpaczaj, mieszkańcu Azeroth!', 0),
(24297, 'plPL', 'Taureńscy Wodzowie zatrzymali się w Srebrnej Lunie, a ja w tym czasie organizuję ich następną trasę. Kiedy nie ćwiczą, często wylegują się na balkonie nade mną. Śmiało im pomachaj... uwielbiają uwagę.\nObecnie nie przyjmujemy nikogo ani do występów, ani do ekipy, ale zawsze możesz zajrzeć później. Kto wie, co się trafi?', '', 0),
(24298, 'plPL', '$GWidziałeś:Widziałaś; ich występ w Puszczy Terokkar? Był niesamowity!', '$GWidziałeś:Widziałaś; ich występ w Puszczy Terokkar? Był niesamowity!', 0),
(24299, 'plPL', 'Taureńscy Wodzowie to chyba najsłynniejsi minstrele w całym Azeroth!', 'Taureńscy Wodzowie to chyba najsłynniejsi minstrele w całym Azeroth!', 0),
(24300, 'plPL', 'Ciekawe, jak długo jeszcze zostaną w Srebrnej Lunie. Mam nadzieję, że tu zagrają!', 'Ciekawe, jak długo jeszcze zostaną w Srebrnej Lunie. Mam nadzieję, że tu zagrają!', 0),
(24301, 'plPL', 'Za szansę, by tam pójść i z nimi porozmawiać, można by oddać prawie wszystko...', 'Za szansę, by tam pójść i z nimi porozmawiać, można by oddać prawie wszystko...', 0),
(24305, 'plPL', 'Dowodzę robotnikami, którzy obsługują Taureńskich Wodzów.\nNo wiesz: pakowanie, powożenie i rozpakowywanie wozów, stawianie i rozbieranie sceny, przygotowywanie pirotechniki, tego typu rzeczy.', '', 0),
(24306, 'plPL', 'Schweitzer to mój stary przyjaciel... cenna rzecz. Przyjaźń, mam na myśli. Myślałem, że zapomniałem, jak to jest, dopóki nie spotkaliśmy się znów w Shattrath.\nNie bywa już tak często w Tirisfal, więc pomyślałem, że skorzystam z Kuli translokacji i wpadnę się przywitać.', '', 0),
(24451, 'plPL', 'Niech będą przeklęci Kael\'thas i jego spaczokrwawi! Wszystko, na co pracowaliśmy, przepadło, ale głupcy z nich, jeśli sądzą, że nie stawimy oporu. Lady Liadrin już szuka dla naszego zakonu nowego źródła mocy. Nie damy się tak łatwo zniszczyć.', '', 0),
(25294, 'plPL', 'Stój!', 'Stój!', 0),
(33118, 'plPL', 'Ach, Miłogrody. Jakże zabawnie patrzeć, jak inni wyzbywają się godności, byle polować na kolorowe jajka. Choć trzeba przyznać, że otacza je osobliwa magiczna aura...', 'Ach, Miłogrody. Jakże zabawnie patrzeć, jak inni wyzbywają się godności, byle polować na kolorowe jajka. Choć trzeba przyznać, że otacza je osobliwa magiczna aura...', 0),
(34706, 'plPL', 'Stój!', '', 0),
(35091, 'plPL', '„Dary Pielgrzymów”. Hm. Rozumiem, że taureni palą się, by okazać wodzowi Hordy wdzięczność i poczucie braterstwa, ale Porzuceni?$B$BWydawałoby się, że dawno wyzbyli się takich sentymentalnych tradycji.', '„Dary Pielgrzymów”. Hm. Rozumiem, że taureni palą się, by okazać wodzowi Hordy wdzięczność i poczucie braterstwa, ale Porzuceni?$B$BWydawałoby się, że dawno wyzbyli się takich sentymentalnych tradycji.', 0),
(35823, 'plPL', 'Chroń niewinnych!', 'Chroń niewinnych!', 0);
